import re
import sys


def main():
    text = sys.stdin.read()

    # Match statements like "x <- 42;" or "x <- y;"
    pattern = re.compile(r'([A-Za-z_]\w*)\s*<-\s*(-?\d+|[A-Za-z_]\w*)\s*;')

    env = {}
    for target, source in pattern.findall(text):
        if re.fullmatch(r'-?\d+', source):
            value = int(source)
        else:
            value = env.get(source, 0)
        env[target] = value

    names = ['a', 'b', 'c', 'd', 'TMP']
    parts = [f"{name} ?= {env.get(name, 0)};" for name in names]
    print(" ".join(parts))


if __name__ == "__main__":
    main()
